openapi: 3.2.1
info: {title: Orders API, version: 2026-10-15}
paths:
  /v1/orders:
    get:
      operationId: listOrders
      parameters:
        - {name: page_size, in: query, schema: {type: integer, default: 25, maximum: 100}}
        - {name: page_token, in: query, schema: {type: string}}
      responses:
        '200': {$ref: '#/components/responses/OrderPage'}
        '429': {$ref: '#/components/responses/Problem'}
    post:
      operationId: createOrder
      responses:
        '201': {description: created, headers: {Location: {schema: {type: string}}}}
        '400': {$ref: '#/components/responses/Problem'}
  /v1/orders/{id}:cancel:
    post:
      operationId: cancelOrder
      responses:
        '200': {description: cancelled}
        '409': {$ref: '#/components/responses/Problem'}
  /v1/exports:
    post:
      operationId: startExport
      responses:
        '202': {description: accepted, headers: {Location: {schema: {type: string}}}}
components:
  responses:
    Problem:
      description: error
      content:
        application/problem+json:
          schema: {$ref: '#/components/schemas/Problem'}
    OrderPage:
      description: one page of orders
  schemas:
    Problem:
      type: object
      properties:
        type: {type: string, format: uri}
        title: {type: string}
        status: {type: integer}
        detail: {type: string}
        instance: {type: string}
        errors: {type: array, items: {type: object}}
